let _lastPick = {};
function pickPh(key) { const a = PH[key] || []; if (!a.length) return ""; let i; do { i = Math.floor(Math.random() * a.length); } while (a.length > 1 && i === _lastPick[key]); _lastPick[key] = i; return a[i]; }
